I found a bug where whitespace is being skipped during digit scanning, causing "1 2" to be parsed as 12. I'll fix the digit-continuation logic to use a raw character check.
```python
def eval_expr(s):
    """Evaluate an arithmetic expression string.

    Supports non-negative integers, + - * / ( ), and unary minus.
    Division is float division. Returns a float.
    """
    pos = [0]
    n = len(s)

    def peek():
        """Return next non-whitespace char (without consuming), or None."""
        i = pos[0]
        while i < n and s[i].isspace():
            i += 1
        pos[0] = i
        return s[i] if i < n else None

    def next_tok():
        """Consume and return next non-whitespace char, or None."""
        i = pos[0]
        while i < n and s[i].isspace():
            i += 1
        if i < n:
            c = s[i]
            pos[0] = i + 1
            return c
        return None

    def peek_raw():
        """Peek at the raw next character (no whitespace skipping)."""
        return s[pos[0]] if pos[0] < n else None

    def parse_expr():
        v = parse_term()
        while True:
            c = peek()
            if c == '+':
                next_tok()
                v += parse_term()
            elif c == '-':
                next_tok()
                v -= parse_term()
            else:
                return v

    def parse_term():
        v = parse_factor()
        while True:
            c = peek()
            if c == '*':
                next_tok()
                v *= parse_factor()
            elif c == '/':
                next_tok()
                v /= parse_factor()
            else:
                return v

    def parse_factor():
        c = peek()
        if c == '+':
            next_tok()
            return parse_factor()
        if c == '-':
            next_tok()
            return -parse_factor()
        return parse_primary()

    def parse_primary():
        c = next_tok()
        if c is None:
            raise ValueError("unexpected end of expression")
        if c == '(':
            v = parse_expr()
            if peek() != ')':
                raise ValueError("expected ')'")
            next_tok()
            return float(v)
        if c.isdigit():
            num = c
            while peek_raw() is not None and peek_raw().isdigit():
                num += next_tok()
            return float(num)
        raise ValueError(f"unexpected character {c!r}")

    result = parse_expr()
    if peek() is not None:
        raise ValueError("unexpected trailing characters")
    return float(result)
```
